local function lx_b64(s)
  s = string.gsub(s, "[^%w%+%/]", "")
  local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  local map = {}
  for i = 1, 64 do map[string.byte(chars, i)] = i - 1 end
  local byte = string.byte
  local out, n = {}, 0
  local len = #s
  local full = len - (len % 4)
  for i = 1, full, 4 do
    local a, b, c, d = byte(s, i, i + 3)
    local v = map[a] * 262144 + map[b] * 4096 + map[c] * 64 + map[d]
    out[n + 1] = math.floor(v / 65536)
    out[n + 2] = math.floor(v / 256) % 256
    out[n + 3] = v % 256
    n = n + 3
  end
  local rem = len - full
  if rem == 2 then
    local a, b = byte(s, full + 1, full + 2)
    local v = map[a] * 262144 + map[b] * 4096
    out[n + 1] = math.floor(v / 65536)
  elseif rem == 3 then
    local a, b, c = byte(s, full + 1, full + 3)
    local v = map[a] * 262144 + map[b] * 4096 + map[c] * 64
    out[n + 1] = math.floor(v / 65536)
    out[n + 2] = math.floor(v / 256) % 256
  end
  return out
end
local function lx_inflate(src)
  local band, rshift, lshift = bit32.band, bit32.rshift, bit32.lshift
