    bitbuf = rshift(val, need)
    bitcnt = bitcnt - need
    return band(val, lshift(1, need) - 1)
  end
  local function construct(lengths, n)
    local count = {}
    for i = 0, 15 do count[i] = 0 end
    for i = 1, n do count[lengths[i]] = count[lengths[i]] + 1 end
    local offs = {}
    offs[1] = 0
    for l = 1, 14 do offs[l + 1] = offs[l] + count[l] end
    local symbol = {}
    for i = 1, n do
      local l = lengths[i]
      if l ~= 0 then
        symbol[offs[l] + 1] = i - 1
        offs[l] = offs[l] + 1
      end
    end
    return {count, symbol}
  end
  local function decode(h)
    local count, symbol = h[1], h[2]
    local code, first, index = 0, 0, 0
