      local sym = decode(lencode)
      if sym < 256 then
        olen = olen + 1
        out[olen] = sym
      elseif sym == 256 then
        return
      else
        sym = sym - 256
        local len = lbase[sym] + bits(lext[sym])
        local ds = decode(distcode) + 1
        local dist = dbase[ds] + bits(dext[ds])
        for _ = 1, len do
          olen = olen + 1
          out[olen] = out[olen - dist]
        end
      end
    end
  end
  local fixedLen, fixedDist
  repeat
    local last = bits(1)
    local typ = bits(2)
    if typ == 0 then
      bitbuf, bitcnt = 0, 0
      local len = src[pos] + src[pos + 1] * 256
      pos = pos + 4
      for _ = 1, len do
        olen = olen + 1
        out[olen] = src[pos]
        pos = pos + 1
      end
    elseif typ == 1 then
      if not fixedLen then
        local l = {}
        for i = 1, 144 do l[i] = 8 end
        for i = 145, 256 do l[i] = 9 end
        for i = 257, 280 do l[i] = 7 end
        for i = 281, 288 do l[i] = 8 end
        fixedLen = construct(l, 288)
