        for i = 1, 30 do d[i] = 5 end
        fixedDist = construct(d, 30)
      end
      codes(fixedLen, fixedDist)
    elseif typ == 2 then
      local nlen = bits(5) + 257
      local ndist = bits(5) + 1
      local ncode = bits(4) + 4
      local order = {17,18,19,1,9,8,10,7,11,6,12,5,13,4,14,3,15,2,16}
      local lengths = {}
      for i = 1, 19 do lengths[i] = 0 end
      for i = 1, ncode do lengths[order[i]] = bits(3) end
      local lencodeH = construct(lengths, 19)
      local idx = 0
