          local prev, rep = 0, 0
          if sym == 16 then
            prev = ll[idx]
            rep = 3 + bits(2)
          elseif sym == 17 then
            rep = 3 + bits(3)
          else
            rep = 11 + bits(7)
          end
          for _ = 1, rep do
            idx = idx + 1
            ll[idx] = prev
          end
        end
      end
      local l1, l2 = {}, {}
      for i = 1, nlen do l1[i] = ll[i] end
      for i = 1, ndist do l2[i] = ll[nlen + i] end
      codes(construct(l1, nlen), construct(l2, ndist))
    else
      error("inflate: bad block type")
    end
  until last == 1
  local parts, np = {}, 0
  local char, unpack = string.char, table.unpack
