local function lx_report(err)
  pcall(function()
    local ex = "?"
    pcall(function() ex = tostring(identifyexecutor and identifyexecutor() or "unknown") end)
    local msg = "[Lexushub] startup error (executor: " .. ex .. ")\n" .. tostring(err)
    warn(msg)
    pcall(function() if setclipboard then setclipboard(msg) end end)
    local parent = (gethui and gethui()) or game:GetService("CoreGui")
    local g = Instance.new("ScreenGui")
    g.Name = "LexushubError"; g.ResetOnSpawn = false; g.DisplayOrder = 2000001; g.IgnoreGuiInset = true
    local f = Instance.new("Frame"); f.Size = UDim2.new(0.9, 0, 0.5, 0); f.Position = UDim2.new(0.05, 0, 0.05, 0)
    f.BackgroundColor3 = Color3.fromRGB(20, 20, 20); f.BorderSizePixel = 0; f.Parent = g
    local tb = Instance.new("TextBox"); tb.Size = UDim2.new(1, -10, 1, -40); tb.Position = UDim2.new(0, 5, 0, 5)
    tb.BackgroundTransparency = 1; tb.TextColor3 = Color3.fromRGB(255, 120, 120); tb.TextXAlignment = Enum.TextXAlignment.Left
    tb.TextYAlignment = Enum.TextYAlignment.Top; tb.TextWrapped = true; tb.TextSize = 14; tb.ClearTextOnFocus = false
    tb.MultiLine = true; tb.TextEditable = false; tb.Text = msg; tb.Parent = f
    local b = Instance.new("TextButton"); b.Size = UDim2.new(1, -10, 0, 30); b.Position = UDim2.new(0, 5, 1, -35)
    b.Text = "Close (error text was copied to clipboard)"; b.Parent = f
    b.MouseButton1Click:Connect(function() g:Destroy() end)
    g.Parent = parent
  end)
end
